action.mutation:
mutation createUpdateInventory($updatePayload: [InventoryUpdatePayloadInput!]!) {
  updateInventory(payload: $updatePayload) {
    id
    number
    quantity {
      value
      unitId
    }
  locationId
  masterInventoryId
  productStrategyProcessId
  inventoryStatusId

  }
}

